CREATE OR REPLACE PROCEDURE sp(
    para_height integer,
    para_birthday text,
    para_player_api_id integer,
    para_id integer,
    para_team_short_name text,
    para_team_fifa_api_id integer
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_post_player_cutoff integer;
BEGIN
    v_post_player_cutoff := para_id;

    UPDATE Player SET birthday = 'phase_1';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 0;
    UPDATE Team SET team_short_name = 'log_phase_1';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 0;

    UPDATE Player SET birthday = 'phase_2';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 1;
    UPDATE Team SET team_short_name = 'log_phase_2';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 1;

    UPDATE Player SET birthday = 'phase_3';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 2;
    UPDATE Team SET team_short_name = 'log_phase_3';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 2;

    UPDATE Player SET birthday = 'phase_4';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 3;
    UPDATE Team SET team_short_name = 'log_phase_4';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 3;

    UPDATE Player SET birthday = 'phase_5';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 4;
    UPDATE Team SET team_short_name = 'log_phase_5';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 4;

    UPDATE Player SET birthday = 'phase_6';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 5;
    UPDATE Team SET team_short_name = 'log_phase_6';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 5;

    UPDATE Player SET birthday = 'phase_7';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 6;
    UPDATE Team SET team_short_name = 'log_phase_7';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 6;

    UPDATE Player SET birthday = 'phase_8';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 7;
    UPDATE Team SET team_short_name = 'log_phase_8';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 7;

    UPDATE Player SET birthday = 'phase_9';
    DELETE FROM Player WHERE player_api_id < para_player_api_id + 8;
    UPDATE Team SET team_short_name = 'log_phase_9';
    DELETE FROM Team WHERE team_fifa_api_id < para_team_fifa_api_id + 8;

    IF para_id > 0 THEN
        UPDATE Player SET birthday = para_birthday WHERE id <= para_id;
    END IF;

    IF para_height IS NOT NULL AND para_height > 0 THEN
        DELETE FROM Player WHERE height < para_height;
    END IF;
END;
$$;

